import sys

def find_inversions_and_sort(n, a):
    # Find all inversions
    inversions = []
    for u in range(n):
        for v in range(u + 1, n):
            if a[u] > a[v]:
                inversions.append((u + 1, v + 1))

    # Check if the array can be sorted by swapping these inversions
    if not inversions:
        return -1

    # Sort the array using the inversions
    sorted_a = a[:]
    for u, v in inversions:
        sorted_a[u - 1], sorted_a[v - 1] = sorted_a[v - 1], sorted_a[u - 1]

    # Verify if the array is sorted
    if sorted_a != sorted(a):
        return -1

    return inversions

